// Starter vocabulary. Line format:  word|part of speech|Uzbek|example sentence
// Topic lists have 40 words each (IELTS-style topics). Extra topics/levels are generated by Gemini and cached
// (see scripts/generate-vocab.js), so the platform is not limited to what is listed here.
const parse = (txt, topic, level) =>
  txt.trim().split('\n').map((l) => {
    const [w, pos, uz, ex] = l.split('|').map((s) => s.trim());
    return { w, pos, uz, ex, topic, level };
  });

